\be \label{eq:prob} \min_{x \in \Rn}~\psi(x) := f(x) + \vp(x),\ee

where $f : \Rn \to \R$ is a continuously differentiable but not necessarily convex function and $\vp : \Rn \to \Rex$ is a convex, lower semicontinuous, and proper mapping. We assume that a full evaluation of the function $f$ and its gradient $\nabla f$ is either too expensive or not  possible and that approximate gradient information can only be accessed via calling \textit{stochastic oracles}. %which give access to stochastic approximations of gradient $\nabla f$ and propose a general stochastic two-step framework. 


By $\iprod{\cdot}{\cdot}$ and $\|\cdot\| := \|\cdot\|_2$ we denote the standard Euclidean inner product and norm. For matrices, the norm $\|\cdot\|$ is the standard spectral norm. The set of symmetric and positive definite $n \times n$ matrices is denoted by $\Spp$. For a given matrix $\Lambda \in \Spp$, we define the inner product $\iprod{x}{y}_\Lambda := \iprod{x}{\Lambda y} = \iprod{\Lambda x}{y}$ and $\|x\|_\Lambda := \sqrt{\iprod{x}{x}_\Lambda}$.
%$|S|$ represents the cardinality of a finite set $S$. If $S$ is a subset of $\{1,2,\dots,n\},$ then for any vector $x\in \R^n$ and matrix $H\in \R^{n\times n}$, $x_{S}$ is the subvector of $x$ whose entries lie in $x$ indexed by $S,$ and $H_{SS}$ represents the submatrix of $H$ whose rows and columns lie in $S$. 
For any $n \in \N$, we set $[n] := \{1,...,n\}$ and $[n]_0 = \{0\} \cup [n]$. Let $(\Omega,\mathcal F,\Prob)$ be a probability space. We will use uppercase letters and a sans-serif letterform to describe random variables ${\sf X} : \Omega \to \Rn$, while lowercase letters or letters with serifs are typically reserved for realizations of a random variable, $x = {\sf X}(\omega)$, or deterministic parameters. We use $L^p(\Omega) := L^p(\Omega,\Prob)$, $p \in [1,\infty]$, to denote the standard $L^p$ space on $\Omega$. We write ${\sf X} \in \mathcal F$ for ``${\sf X}$ is $\mathcal F$-measurable''. Moreover, $\sigma({\sf X}^1,...,{\sf X}^k)$ denotes the $\sigma$-algebra generated by the family of random variables ${\sf X}^1,...,{\sf X}^k$. For a random variable ${\sf X} \in L^1(\Omega)$ and a sub-$\sigma$-algebra $\cH \subseteq \mathcal F$, the conditional expectation of ${\sf X}$ given $\cH$ is denoted by $\Exp[{\sf X} \mid \cH]$. We use the abbreviations ``a.e.'' and ``a.s.'' for ``almost everywhere'' and ``almost surely'', respectively.


\subsection{Preliminaries and First Order Optimality} It is well-known that the stationarity conditions of problem \eqref{eq:prob} can be equivalently rewritten as a proximal fixed-point equation, i.e., a point $x \in \dom~\vp$ is a critical point of \eqref{eq:prob} if and only if
%
\be \label{eq:opt} F^\Lambda(x) := x - \proxt{\Lambda}{\vp}(x-\Lambda^{-1}\nabla f(x)) = 0, \quad \Lambda \in \Spp, \ee

where $\proxt{\Lambda}{\vp} : \Rn \to \Rn$, $\proxt{\Lambda}{\vp}(x) := \argmin_y \vp(y) + \frac{1}{2}\|x-y\|^2_\Lambda$ denotes the proximity operator of the mapping $\vp$. The proximity operator is a $\Lambda$-firmly nonexpansive function, i.e., it is globally Lipschitz continuous and satisfies
%
\be \label{eq:prox-nonexp} \|\proxt{\Lambda}{\vp}(x) - \proxt{\Lambda}{\vp}(y)\|_\Lambda^2 \leq \iprod{\Lambda(x-y)}{\proxt{\Lambda}{\vp}(x) - \proxt{\Lambda}{\vp}(y)}, \quad \forall~x,y. \ee

The proximity operator $\proxt{\Lambda}{\vp}$ can also be alternatively characterized via the underlying optimality condition
%
\be \label{eq:prox-opt} \proxt{\Lambda}{\vp}(x) \in x - \Lambda^{-1} \partial \vp(\proxt{\Lambda}{\vp}(x)), \ee

Given a generic (stochastic) oracle represented by a direction $v \in \Rn$, we consider inexact variants of the nonsmooth residual \eqref{eq:opt} of the type
%
\begin{equation}
\label{sto_app_optimal}  F^\Lambda_v(x) := x - \proxt{\Lambda}{\vp}(x- \Lambda^{-1} v). 
\end{equation}

We will also use $u^\Lambda_v(x) := x - \Lambda^{-1} v$ and $p^\Lambda_v := \proxt{\Lambda}{\vp}(u^\Lambda_v(x))$ to denote the inexact (proximal) gradient steps. In the case $v \equiv \nabla f(x)$, the terms $u^\Lambda$ and $p^\Lambda$ are used to denote the exact or full gradient and proximal gradient step.


\begin{algorithm2e}[t]
\caption{\textbf{S}tochastic \textbf{E}xtra-Step \textbf{Q}uasi-\textbf{N}ewton Method}    
\label{alg:seqn}
\lnlset{alg:seqn-1}{1}{Initialization: ~~Select the parameter matrices $(\Lambda_k)_k, (\Lambda_{k,+})_k \in \Spp$. Choose the step sizes $(\alpha_k)_k$, $(\beta_k)_k$ and the initial point  $x^0 \in \dom~\vp$ .} \\ 
\For{$k = 0,1,... $}{
\lnlset{alg:seqn-2}{2}{Based on $v^k \approx \nabla f(x^k)$, compute a direction $d^k$ and set $z^k = x^k + \beta_k d^k$.} \\
\lnlset{alg:seqn-3}{3}{Calculate the new oracle $v^k_+ \approx \nabla f(z^k)$ and perform the update \\
\begin{center} $x^{k+1} = \proxt{\Lambda_{k,+}}{\vp}(x^k + \alpha_k d^k - \Lambda_{k,+}^{-1}v^k_+)$ \vspace{-1ex}.\end{center}}  
} 
\end{algorithm2e}

\begin{assumption} \label{ass:lip} Let $f : \Rn \to \R$ be given. We assume: %\vspace{.5ex}
\setlength{\leftmargini}{7ex}
\begin{itemize}
\item[{\rm(A.1)}] The gradient mapping $\nabla f$ is Lipschitzian on $\Rn$ with modulus $L_f \geq 1$. %Moreover, each of the component functions $\nabla f_i$, $i \inÃÂ [N]$, is $L_i$-Lipschitz continuous.\vspace{.5ex} 
\item[{\rm(A.2)}] The objective function $\psi$ is bounded from below on $\dom~\vp$. \vspace{.5ex}
%\item[{\rm(A.3)}] There exist parameters $\mu_f \in \R$ and $\mu_\vp \geq 0$ with $\bar\mu := \mu_f + \mu_\vp > 0$ such that the shifted functions $f - \frac{\mu_f}{2}\|\cdot\|^2$ and $\vp - \frac{\mu_\vp}{2}\|\cdot\|^2$ are convex. \vspace{.5ex}
%\item[{\rm(A.4)}] There exists a constant $\bar g_r > 0$ such that for all $x \in \dom~r$ there exists $\lambda \in \partial r(x)$ with $\|\lambda\| \leq \bar g_r$.
\end{itemize}
\end{assumption}

\be \label{eq:lip-ineq} f(y) \leq f(x) + \iprod{\nabla f(x)}{y-x} + \frac{L_f}{2}  \|y-x\|^2, \quad \forall~x,y \in \Rn, \ee

which is a direct consequence of assumption {\rm(A.1)}.


The stochasticity in Algorithm \ref{alg:seqn} mainly results from the random selection of the oracles $v^k$ and $v^k_+$ in step \ref{alg:seqn-2} and \ref{alg:seqn-3}. In this work, we assume that the stochastic approximations $v^k$ and $v^k_+$ correspond to realizations of the random vectors ${\sf V}^k : \Omega \to \Rn$ and ${\sf V}^k_+ : \Omega \to \Rn$. Furthermore, we suppose that the underlying probability space $(\Omega,\mathcal F,\Prob)$ is sufficiently rich allowing us to model the involved random processes in a unified way. We now define the filtrations
%
\[ \mathcal F^k := \sigma({\sf V}^0, {\sf V}^0_+, ..., {\sf V}^k), \quad \mathcal F^k_+ := \sigma(\mathcal F^k \cup \sigma({\sf V}^k_+)). \]
%
By convention, let $({\sf D}^k)_k$ denote the stochastic process associated with the directions $(d^k)_k$ chosen in step \ref{alg:seqn-2}. We will work with the following stochastic assumptions. 


\begin{assumption} \label{ass:stoch-1} We assume: 
\setlength{\leftmargini}{7ex}
\begin{itemize}
\item[{\rm(B.1)}] The mapping ${\sf D}^k : \Omega \to \R^{n}$ is an $\mathcal F^k$-measurable function for all $k$. \vspace{.5ex} 
\item[{\rm(B.2)}] There is $\nu_k > 0$ such that we have $\Exp[\|{\sf D}^k\|^2 \mid \mathcal F^{k-1}_+] \leq \nu_k^2 \cdot \Exp[\|F^{\Lambda_k}_{{\sf V}^k}({\sf X}^k)\|^2 \mid \mathcal F^{k-1}_+]$ \aev and for all $k \in \N$.
\item[{\rm(B.3)}] For all $k \in \N$, it holds $\Exp[{\sf V}^k \mid \mathcal F^{k-1}_+] = \nabla f({\sf X}^k)$, $\Exp[{\sf V}^k_+ \mid \mathcal F^{k}] = \nabla f({\sf Z}^k)$ \aev and there exists $\sigma_k, \sigma_{k,+} > 0$ such that \aev 
%\item[{\rm(A.3)}] There exist parameters $\mu_f \in \R$ and $\mu_\vp \geq 0$ with $\bar\mu := \mu_f + \mu_\vp > 0$ such that the shifted functions $f - \frac{\mu_f}{2}\|\cdot\|^2$ and $\vp - \frac{\mu_\vp}{2}\|\cdot\|^2$ are convex. \vspace{.5ex}
%\item[{\rm(A.4)}] There exists a constant $\bar g_r > 0$ such that for all $x \in \dom~r$ there exists $\lambda \in \partial r(x)$ with $\|\lambda\| \leq \bar g_r$.
\end{itemize}
%
\[ \Exp[\|\nabla f({\sf X}^k) - {\sf V}^k\|^2 \mid \mathcal F_+^{k-1}] \leq \sigma_k^2 \quad \text{and} \quad \Exp[\|\nabla f({\sf Z}^k) - {\sf V}_+^k\|^2 \mid \mathcal F^{k}] \leq \sigma_{k,+}^2. \]
\end{assumption}

\be \label{eq:prop-stoch} {\sf Z}^k \in \mathcal F^k \quad \text{and} \quad {\sf X}^{k+1} \in {\mathcal F}^{k}_+ , \quad \forall~k \geq 0. \ee

